import{_ as t,o,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Accounting Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Accounting Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/accounting-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Accounting Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/accounting-overview"}]]},"headers":[],"relativePath":"user-guide/accounting-overview.md","filePath":"user-guide/accounting-overview.md","lastUpdated":1787339821000}'),i={name:"user-guide/accounting-overview.md"};function r(c,e,s,d,l,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="accounting-module" tabindex="-1">Accounting Module <a class="header-anchor" href="#accounting-module" aria-label="Permalink to &quot;Accounting Module&quot;">​</a></h1><p>Phase 6 Finance module on the frozen platform. Provides the financial backbone: <strong>chart of accounts</strong>, <strong>manual journal entries</strong> (draft → post → void), <strong>account transfers</strong>, and <strong>general ledger inquiry</strong>. Single-currency. Soft auto-post from <strong>Payments</strong> (deposit) and <strong>Expenses</strong> (paid from) when those modules are entitled alongside Accounting.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/accounting">accounting.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/accounting">accounting.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/accounting">accounting.md</a></td></tr><tr><td>Financial Reports</td><td><a href="/user-guide/financial-reports-overview">financial-reports-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-accounting">../api/tenant-v1-accounting.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Chart of accounts with types <code>asset</code> | <code>liability</code> | <code>equity</code> | <code>revenue</code> | <code>expense</code></li><li><strong>Cash / bank</strong> flag (<code>is_cash_bank</code>) on asset accounts; starter Cash <code>1000</code> is cash/bank; add multiple banks as custom asset + cash/bank</li><li><strong>Current balance</strong> on account list/show (from posted journal lines)</li><li><strong>Set balance</strong> on cash/bank accounts: target amount posts a delta journal (<code>ADJ-</code>); default offset Owner Equity <code>3000</code>; voidable history on the account</li><li>Starter system accounts seeded on first Accounts list (Cash, AR, AP, Equity, Revenue, common expenses)</li><li>Journal entries with balanced debit/credit lines (<code>JE-</code> numbers)</li><li>Lifecycle: <strong>draft → post → void</strong> (voided entries excluded from GL and reports)</li><li><strong>Account transfers</strong> (<code>TRF-</code> numbers): move money between cash/bank accounts (auto-posted journal; void reverses)</li><li>Soft cash movements from <a href="/user-guide/payments-overview">Payments</a> (Deposit to) and <a href="/user-guide/expenses-overview">Expenses</a> (Paid from) when Accounting is installed</li><li>General ledger inquiry over posted lines with optional account and date filters</li><li>Module licensing (<code>module:accounting</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Soft dependency optional later: Inventory COGS / valuations (not in this MVP)</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>accounting.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>post</code> · <code>void</code></p><p>Catalog: slug <code>accounting</code>, category <code>finance</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 10</code>. Version <strong>1.2.0</strong>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Auto-posting from Invoices / Credit Notes / Purchase Orders / Inventory (AR still moves on payment post; AP/COGS not yet)</li><li>Multi-currency accounting / FX on transfers</li><li>Fiscal year close / period locks</li><li>Bank reconciliation and budgets</li><li>Split a single payment across multiple deposit accounts</li><li>Expense unpay / reverse paid journal from the expense record</li></ul>',11)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
